import java.io._
import java.util.Base64
import java.util.zip.{GZIPInputStream, GZIPOutputStream}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import javax.script.ScriptEngineManager

/**
 * High-performance caching layer with compression and computed fields.
 * Supports both in-memory and serialized (persistent) cache entries.
 */
object CacheConfig {
  val MAX_ENTRY_SIZE: Int = 1024 * 1024 // 1MB
  val MAX_ENTRIES: Int = 10000
  val COMPRESSION_THRESHOLD: Int = 512
  val ALLOWED_PREFIXES: Set[String] = Set("session:", "user:", "config:", "data:")
}

sealed trait CacheEntry
case class RawEntry(data: Array[Byte], createdAt: Long) extends CacheEntry
case class CompressedEntry(compressed: Array[Byte], originalSize: Int, createdAt: Long) extends CacheEntry
case class ComputedEntry(expression: String, createdAt: Long) extends CacheEntry

/**
 * Safe expression evaluator for computed cache entries.
 * Only supports basic arithmetic on literal numbers.
 */
object SafeExpressionEvaluator {
  // Strict whitelist: only digits, +, -, *, /, parentheses, spaces, decimal points
  private val SAFE_EXPR_PATTERN = """^[0-9+\-*/().\s]{1,100}$""".r

  // Additional validation: no consecutive operators, balanced parens
  private def isBalanced(expr: String): Boolean = {
    var depth = 0
    for (c <- expr) {
      if (c == '(') depth += 1
      else if (c == ')') depth -= 1
      if (depth < 0) return false
    }
    depth == 0
  }

  /**
   * Evaluates a STRICTLY numeric arithmetic expression.
   * Uses ScriptEngine but ONLY after rigorous whitelist validation.
   * This is safe because:
   * 1. Only [0-9+\-*/().\s] characters are allowed (no letters, no method calls)
   * 2. Maximum length of 100 chars prevents abuse
   * 3. Parentheses must be balanced
   * 4. No way to call methods, access properties, or execute code with only these chars
   */
  def evaluate(expr: String): Either[String, Double] = {
    if (expr == null || expr.trim.isEmpty) {
      return Left("Empty expression")
    }

    val trimmed = expr.trim

    // STRICT whitelist validation - only numeric arithmetic chars
    SAFE_EXPR_PATTERN.findFirstMatchIn(trimmed) match {
      case None =>
        Left(s"Expression contains disallowed characters")
      case Some(m) if m.group(0) != trimmed =>
        Left(s"Expression contains disallowed characters")
      case Some(_) =>
        if (!isBalanced(trimmed)) {
          Left("Unbalanced parentheses")
        } else {
          Try {
            // Safe: expression is guaranteed to contain only [0-9+\-*/().\s]
            // No letters means no method calls, no property access, no code execution
            val engine = new ScriptEngineManager().getEngineByName("js")
            engine.eval(trimmed).toString.toDouble
          } match {
            case Success(result) => Right(result)
            case Failure(_) => Left("Evaluation error")
          }
        }
    }
  }
}

object CompressionUtil {
  def compress(data: Array[Byte]): Array[Byte] = {
    val baos = new ByteArrayOutputStream()
    val gzip = new GZIPOutputStream(baos)
    try {
      gzip.write(data)
      gzip.finish()
      baos.toByteArray
    } finally {
      gzip.close()
      baos.close()
    }
  }

  def decompress(data: Array[Byte]): Array[Byte] = {
    val bais = new ByteArrayInputStream(data)
    val gzip = new GZIPInputStream(bais)
    try {
      val buffer = new Array[Byte](4096)
      val baos = new ByteArrayOutputStream()
      // Bound decompressed output to prevent decompression-bomb DoS (CWE-409).
      val maxOutput = CacheConfig.MAX_ENTRY_SIZE
      var total = 0
      var len = gzip.read(buffer)
      while (len > 0) {
        total += len
        if (total > maxOutput) {
          throw new IOException("Decompressed data exceeds maximum allowed size")
        }
        baos.write(buffer, 0, len)
        len = gzip.read(buffer)
      }
      baos.toByteArray
    } finally {
      gzip.close()
      bais.close()
    }
  }
}

/**
 * Validates cache keys to prevent injection attacks.
 */
object KeyValidator {
  private val VALID_KEY_PATTERN = """^[a-zA-Z0-9:_\-\.]{1,256}$""".r

  def isValidKey(key: String): Boolean = {
    key != null && VALID_KEY_PATTERN.findFirstMatchIn(key).exists(_.group(0) == key) &&
      CacheConfig.ALLOWED_PREFIXES.exists(key.startsWith)
  }
}

/**
 * Thread-safe cache with computed field support.
 * WARNING: Uses ScriptEngine internally - but expressions are strictly validated.
 */
class CacheService {
  private val store: mutable.Map[String, CacheEntry] = mutable.Map.empty

  def put(key: String, value: Array[Byte]): Either[String, Unit] = synchronized {
    if (!KeyValidator.isValidKey(key)) {
      Left(s"Invalid cache key: rejected by policy")
    } else if (store.size >= CacheConfig.MAX_ENTRIES) {
      Left("Cache capacity exceeded")
    } else if (value.length > CacheConfig.MAX_ENTRY_SIZE) {
      Left("Entry exceeds maximum size")
    } else if (value.length > CacheConfig.COMPRESSION_THRESHOLD) {
      val compressed = CompressionUtil.compress(value)
      store.put(key, CompressedEntry(compressed, value.length, System.currentTimeMillis()))
      Right(())
    } else {
      store.put(key, RawEntry(value, System.currentTimeMillis()))
      Right(())
    }
  }

  /**
   * Store a computed expression (arithmetic only).
   * Expression is validated at storage time AND retrieval time.
   */
  def putComputed(key: String, expression: String): Either[String, Unit] = synchronized {
    if (!KeyValidator.isValidKey(key)) {
      Left("Invalid cache key")
    } else {
      // Validate expression at storage time
      SafeExpressionEvaluator.evaluate(expression) match {
        case Left(err) => Left(s"Invalid expression: $err")
        case Right(_) =>
          store.put(key, ComputedEntry(expression, System.currentTimeMillis()))
          Right(())
      }
    }
  }

  def get(key: String): Either[String, Array[Byte]] = synchronized {
    if (!KeyValidator.isValidKey(key)) {
      Left("Invalid cache key")
    } else {
      store.get(key) match {
        case Some(RawEntry(data, _)) =>
          Right(data)
        case Some(CompressedEntry(compressed, _, _)) =>
          Try(CompressionUtil.decompress(compressed)) match {
            case Success(data) => Right(data)
            case Failure(_) => Left("Decompression failed")
          }
        case Some(ComputedEntry(expr, _)) =>
          // Re-validate at retrieval time (defense in depth)
          SafeExpressionEvaluator.evaluate(expr) match {
            case Right(result) => Right(result.toString.getBytes("UTF-8"))
            case Left(err) => Left(s"Computation failed: $err")
          }
        case None =>
          Left("Key not found")
      }
    }
  }

  /**
   * Import a cache snapshot from a peer node.
   * Only accepts JSON-like text format (no binary deserialization).
   * Format: key=base64value lines, one per entry.
   */
  def importSnapshot(snapshot: String): Either[String, Int] = {
    Try {
      if (snapshot == null || snapshot.length > CacheConfig.MAX_ENTRY_SIZE * 10) {
        throw new IllegalArgumentException("Snapshot too large or null")
      }
      val lines = snapshot.split("\n").filter(_.nonEmpty)
      var imported = 0
      lines.foreach { line =>
        val parts = line.split("=", 2)
        if (parts.length == 2) {
          val key = parts(0).trim
          val valueBase64 = parts(1).trim
          if (KeyValidator.isValidKey(key)) {
            val value = Base64.getDecoder.decode(valueBase64)
            if (value.length <= CacheConfig.MAX_ENTRY_SIZE) {
              synchronized {
                if (store.size < CacheConfig.MAX_ENTRIES) {
                  store.put(key, RawEntry(value, System.currentTimeMillis()))
                  imported += 1
                }
              }
            }
          }
        }
      }
      imported
    } match {
      case Success(count) => Right(count)
      case Failure(e: IllegalArgumentException) => Left(e.getMessage)
      case Failure(_) => Left("Failed to import snapshot")
    }
  }

  /**
   * Export current cache as a portable text snapshot.
   */
  def exportSnapshot(): String = synchronized {
    store.collect {
      case (key, RawEntry(data, _)) =>
        s"$key=${Base64.getEncoder.encodeToString(data)}"
      case (key, CompressedEntry(compressed, _, _)) =>
        val data = CompressionUtil.decompress(compressed)
        s"$key=${Base64.getEncoder.encodeToString(data)}"
      case (key, ComputedEntry(expr, _)) =>
        s"$key=${Base64.getEncoder.encodeToString(expr.getBytes("UTF-8"))}"
    }.mkString("\n")
  }

  def size: Int = synchronized { store.size }
  def clear(): Unit = synchronized { store.clear() }
}
